#include <stdio.h>
#include <string.h>

#include "inventory.h"

enum { LINE_CAPACITY = 64 };
enum LineStatus { LINE_EOF, LINE_OK, LINE_INVALID, LINE_IO_ERROR };

static enum LineStatus read_line(FILE *stream, char line[LINE_CAPACITY])
{
    size_t used = 0;
    int byte;
    while ((byte = fgetc(stream)) != EOF && byte != '\n') {
        if (byte == 0 || used == LINE_CAPACITY - 1) {
            return LINE_INVALID;
        }
        line[used++] = (char)byte;
    }
    line[used] = '\0';
    if (byte != EOF) {
        return LINE_OK;
    }
    if (ferror(stream)) {
        return LINE_IO_ERROR;
    }
    return used == 0 ? LINE_EOF : LINE_OK;
}

static int read_number(const char **cursor, int minimum, int *value)
{
    const char *p = *cursor;
    unsigned digits = 0;
    int number = 0;
    while (*p >= '0' && *p <= '9') {
        if (++digits > 4) {
            return 0;
        }
        number = number * 10 + (*p++ - '0');
    }
    if (digits == 0 || number < minimum) {
        return 0;
    }
    *cursor = p;
    *value = number;
    return 1;
}

static const char *load_records(Inventory *stock)
{
    FILE *input = fopen("records.tsv", "rb");
    if (input == NULL) {
        return "open-input-error";
    }
    const char *problem = NULL;
    char line[LINE_CAPACITY];
    enum LineStatus status;
    while ((status = read_line(input, line)) == LINE_OK) {
        const char *p = line;
        Record record;
        if (!read_number(&p, 1, &record.id) || *p++ != '\t' ||
            !read_number(&p, 0, &record.quantity) || *p != '\0') {
            problem = "invalid-record";
        } else if (inventory_find(stock, record.id) != NULL) {
            problem = "duplicate-id";
        } else if (stock->count == INVENTORY_CAPACITY) {
            problem = "capacity-error";
        } else {
            stock->records[stock->count++] = record;
        }
        if (problem != NULL) {
            break;
        }
    }
    if (problem == NULL && status != LINE_EOF) {
        problem = status == LINE_IO_ERROR ? "read-input-error" : "invalid-record";
    }
    if (fclose(input) != 0 && problem == NULL) {
        problem = "close-input-error";
    }
    return problem;
}

static const char *write_report(const Inventory *stock)
{
    FILE *output = fopen("example-summary.tsv", "wb");
    if (output == NULL) {
        return "open-report-error";
    }
    const char *problem = NULL;
    if (fputs("id\tquantity\n", output) == EOF) {
        problem = "write-report-error";
    }
    for (size_t i = 0; problem == NULL && i < stock->count; ++i) {
        const Record *record = &stock->records[i];
        if (fprintf(output, "%d\t%d\n", record->id, record->quantity) < 0) {
            problem = "write-report-error";
        }
    }
    if (fclose(output) != 0 && problem == NULL) {
        problem = "close-report-error";
    }
    return problem;
}

static int run_command(Inventory *stock, const char *line)
{
    int id;
    if (strncmp(line, "find ", 5) == 0) {
        const char *p = line + 5;
        if (read_number(&p, 1, &id) && *p == '\0') {
            const Record *match = inventory_find(stock, id);
            if (match == NULL) {
                puts("missing");
            } else {
                printf("%d %d\n", match->id, match->quantity);
            }
            return 0;
        }
    } else if (strncmp(line, "set ", 4) == 0) {
        const char *p = line + 4;
        int quantity;
        if (read_number(&p, 1, &id) && *p++ == ' ' &&
            read_number(&p, 0, &quantity) && *p == '\0') {
            puts(inventory_set(stock, id, quantity) ? "ok" : "missing");
            return 0;
        }
    } else if (strcmp(line, "report") == 0) {
        const char *problem = write_report(stock);
        if (problem != NULL) {
            fprintf(stderr, "%s\n", problem);
            return 3;
        }
        puts("reported");
        return 0;
    }
    puts("invalid");
    return 2;
}

int main(void)
{
    Inventory stock = {0};
    const char *problem = load_records(&stock);
    if (problem != NULL) {
        fprintf(stderr, "%s\n", problem);
        return 1;
    }
    char line[LINE_CAPACITY];
    enum LineStatus status;
    while ((status = read_line(stdin, line)) == LINE_OK) {
        int exit_status = run_command(&stock, line);
        if (exit_status != 0) {
            return exit_status;
        }
    }
    if (status == LINE_INVALID) {
        puts("invalid");
        return 2;
    }
    if (status == LINE_IO_ERROR) {
        fputs("read-command-error\n", stderr);
        return 2;
    }
    return 0;
}

